36	/// A resolved command permission.
37	#[derive(Default, Clone, PartialEq, Eq)]
38	pub struct ResolvedCommand {
39	  /// The list of capability/permission that referenced this command.
40	  #[cfg(debug_assertions)]
41	  pub referenced_by: Vec<ResolvedCommandReference>,
42	  /// The list of window label patterns that was resolved for this command.
43	  pub windows: Vec<glob::Pattern>,
