60	/// A resolved scope. Merges all scopes defined for a single command.
61	#[derive(Debug, Default)]
62	pub struct ResolvedScope {
63	  /// Allows something on the command.
64	  pub allow: Vec<Value>,
65	  /// Denies something on the command.
66	  pub deny: Vec<Value>,
67	}
