69	/// A command key for the map of allowed and denied commands.
70	/// Takes into consideration the command name and the execution context.
71	#[derive(Debug, Clone, Eq, PartialEq, PartialOrd, Ord, Hash)]
72	pub struct CommandKey {
73	  /// The full command name.
74	  pub name: String,
75	  /// The context of the command.
76	  pub context: ExecutionContext,
77	}
