202	impl RuntimeAuthority {
203	  #[doc(hidden)]
204	  pub fn new(acl: BTreeMap<String, Manifest>, resolved_acl: Resolved) -> Self {
205	    let command_cache = resolved_acl
206	      .command_scope
207	      .keys()
208	      .map(|key| (*key, <TypeMap![Send + Sync]>::new()))
209	      .collect();
210	    Self {
211	      acl,
212	      allowed_commands: resolved_acl.allowed_commands,
213	      denied_commands: resolved_acl.denied_commands,
214	      scope_manager: ScopeManager {
215	        command_scope: resolved_acl.command_scope,
216	        global_scope: resolved_acl.global_scope,
217	        command_cache,
218	        global_scope_cache: Default::default(),
219	      },
220	    }
221	  }
222	
223	  pub(crate) fn has_app_manifest(&self) -> bool {
224	    self.acl.contains_key(APP_ACL_KEY)
225	  }
226	
227	  #[doc(hidden)]
228	  pub fn __allow_command(&mut self, command: String, context: ExecutionContext) {
229	    self.allowed_commands.insert(
230	      CommandKey {
231	        name: command,
232	        context,
233	      },
234	      ResolvedCommand {
235	        windows: vec!["*".parse().unwrap()],
236	        ..Default::default()
237	      },
238	    );
239	  }
240	
241	  /// Adds the given capability to the runtime authority.
242	  pub fn add_capability(&mut self, capability: impl RuntimeCapability) -> crate::Result<()> {
243	    let mut capabilities = BTreeMap::new();
244	    match capability.build() {
245	      CapabilityFile::Capability(c) => {
246	        capabilities.insert(c.identifier.clone(), c);
247	      }
248	      CapabilityFile::List {
249	        capabilities: capabilities_list,
250	      } => {
251	        capabilities.extend(
252	          capabilities_list
253	            .into_iter()
254	            .map(|c| (c.identifier.clone(), c)),
255	        );
256	      }
257	    }
258	
259	    let resolved = Resolved::resolve(
260	      &self.acl,
261	      capabilities,
262	      tauri_utils::platform::Target::current(),
263	    )
264	    .unwrap();
265	
