219	#[cfg(feature = "build")]
220	mod build_ {
221	  use std::convert::identity;
222	
223	  use crate::{literal_struct, tokens::*};
224	
225	  use super::*;
226	  use proc_macro2::TokenStream;
227	  use quote::{quote, ToTokens, TokenStreamExt};
228	
229	  impl ToTokens for ExecutionContext {
230	    fn to_tokens(&self, tokens: &mut TokenStream) {
231	      let prefix = quote! { ::tauri::utils::acl::ExecutionContext };
232	
233	      tokens.append_all(match self {
234	        Self::Local => {
235	          quote! { #prefix::Local }
236	        }
237	        Self::Remote { url } => {
238	          let url = url.as_str();
239	          quote! { #prefix::Remote { url: #url.parse().unwrap() } }
240	        }
241	      });
242	    }
243	  }
244	
245	  impl ToTokens for Commands {
246	    fn to_tokens(&self, tokens: &mut TokenStream) {
